test.describe('code-runner tools', () => {
  const P = 'code_runner_';
  test.beforeEach(async ({ page }) => {
    await fakeModelContext(page);
    await page.goto('/code-runner/');
  });

  test('run_code: JavaScript and Python run in the app, the result comes back and is shown', async ({ page }) => {
    const tools = await listTools(page);
    expect(tools.find(t => t.name === P + 'run_code').annotations).toEqual({ readOnlyHint: false });
    expect(tools.find(t => t.name === P + 'get_code').annotations).toEqual({ readOnlyHint: true, untrustedContentHint: true });
    expect(tools.find(t => t.name === P + 'get_output').annotations).toEqual({ readOnlyHint: true, untrustedContentHint: true });
    expect((await call(page, P + 'get_output', {})).result).toEqual({ has_run: false, running: false });

    // 1 + 2 + … + 100 = 5050; 12! = 479001600
    let r = await call(page, P + 'run_code', { language: 'javascript', code: 'let s = 0;\nfor (let i = 1; i <= 100; i++) s += i;\nconsole.log("sum", s);\nconsole.error("note");\nprompt()', stdin: 'typed\n' });
    expect(r.ok).toBe(true);
    expect(r.result).toEqual({ language: 'javascript', status: 'finished', stdout: 'sum 5050\n', stderr: 'note\n', result: '"typed"',
      error: null, duration_ms: expect.any(Number), output_truncated: false });
    await expect(page.locator('#langs [data-l="javascript"]')).toHaveAttribute('aria-pressed', 'true');
    await expect(page.locator('#code')).toHaveValue(/s \+= i;/);
    await expect(page.locator('#out')).toHaveText('sum 5050\nnote\ntyped\n→ "typed"\n');
    await expect(page.locator('#toast')).toHaveText('KI-Agent: Code ausgeführt');

    r = await call(page, P + 'run_code', { language: 'python', code: 'import math\nprint(math.factorial(12))\nint(input()) * 2', stdin: '21' });
    expect(r.result).toMatchObject({ language: 'python', status: 'finished', stdout: '479001600\n', stderr: '', result: '42', error: null });
    await expect(page.locator('#langs [data-l="python"]')).toHaveAttribute('aria-pressed', 'true');

    expect((await call(page, P + 'get_code', {})).result).toEqual({ language: 'python', code: 'import math\nprint(math.factorial(12))\nint(input()) * 2', stdin: '' });
    expect((await call(page, P + 'get_output', {})).result).toMatchObject({ has_run: true, running: false, language: 'python', status: 'finished', stdout: '479001600\n', result: '42' });
  });

  test('run_code: errors with line, timeout, invalid input; unsaved code of the user is kept as a script', async ({ page }) => {
    await page.locator('#langs [data-l="javascript"]').click();
    await page.locator('#code').fill('// my own work');
    let r = await call(page, P + 'run_code', { language: 'javascript', code: 'console.log("a");\nnull.x' });
    expect(r.result).toMatchObject({ status: 'error', stdout: 'a\n', result: null, error: { message: expect.stringMatching(/^TypeError: /), line: 2 } });
    expect(r.result.stderr).toMatch(/^TypeError: .*\(Zeile 2\)\n$/);
    const scripts = await page.evaluate(() => JSON.parse(localStorage.getItem('code-runner.scripts.v1')));
    expect(scripts.map(s => [s.lang, s.code])).toEqual([['javascript', '// my own work']]);
    expect(scripts[0].name).toMatch(/^Entwurf /);
    // The agent's own code is not kept again
    await call(page, P + 'run_code', { language: 'javascript', code: '1' });
    expect(await page.evaluate(() => JSON.parse(localStorage.getItem('code-runner.scripts.v1')).length)).toBe(1);

    r = await call(page, P + 'run_code', { language: 'python', code: 'def f():\n    raise ValueError("bad")\nf()' });
    // line = where the error was raised (innermost frame of the program), the traceback names both
    expect(r.result).toMatchObject({ status: 'error', error: { line: 2 } });
    expect(r.result.stderr).toContain('File "main.py", line 3, in <module>');
    expect(r.result.error.message).toMatch(/ValueError: bad$/);

    r = await call(page, P + 'run_code', { language: 'javascript', code: 'console.log("start");\nwhile (true) {}', timeout_seconds: 1 });
    expect(r.result).toMatchObject({ status: 'timed_out', stdout: 'start\n' });
    await expect(page.locator('#status')).toHaveText('Abgebrochen nach 1 s');
    expect((await call(page, P + 'run_code', { language: 'javascript', code: '2 + 2' })).result.result).toBe('4');

    for (const [input, msg] of [
      [{ language: 'bash', code: 'ls' }, /input.language must be one of: python, javascript/],
      [{ language: 'python' }, /input.code is required/],
      [{ language: 'python', code: '' }, /at least 1 characters/],
      [{ language: 'python', code: '1', timeout_seconds: 500 }, /must be <= 120/],
      [{ language: 'python', code: '1', packages: ['numpy'] }, /input.packages is not allowed/],
    ]) expect((await call(page, P + 'run_code', input)).error).toMatch(msg);
    await expect(page.locator('#code')).toHaveValue('2 + 2');
  });

  test('run_code: refused while a program is running; get_output reads the output so far; no network', async ({ page }) => {
    await page.locator('#langs [data-l="javascript"]').click();
    await page.locator('#code').fill('console.log("tick");\nsetInterval(() => {}, 1000);');
    await page.locator('#btnRun').click();
    await expect(page.locator('#out')).toHaveText('tick\n');
    expect((await call(page, P + 'run_code', { language: 'javascript', code: '1' })).error).toMatch(/still running/);
    expect((await call(page, P + 'get_output', {})).result).toMatchObject({ has_run: true, running: true, status: 'running', stdout: 'tick\n' });
    await page.locator('#btnRun').click();
    expect((await call(page, P + 'get_output', {})).result).toMatchObject({ running: false, status: 'stopped', stdout: 'tick\n' });
    const r = await call(page, P + 'run_code', { language: 'javascript', code: 'return await fetch("https://example.com/").then(() => "sent", e => e.message)' });
    expect(r.result.result).toBe('"fetch is blocked: code in this app runs without network access"');
  });
});

test.describe('calc-pad tools', () => {
  test.use({ locale: 'de-DE' });
  test.beforeEach(async ({ page }) => { await open(page, '/calc-pad/'); });

  test('calculate returns the number and leaves the pad alone', async ({ page }) => {
    const tools = await listTools(page);
    expect(tools.find(t => t.name === 'calc_pad_calculate').annotations.readOnlyHint).toBe(true);
    expect(tools.find(t => t.name === 'calc_pad_read_pad').annotations).toEqual({ readOnlyHint: true, untrustedContentHint: true });
    expect(tools.find(t => t.name === 'calc_pad_add_lines').annotations.readOnlyHint).toBe(false);
    // (850 + 120) * 12 = 11640; 200 + 10 % of 200 = 220; 2^10 + sqrt(16) = 1028; agents always use the decimal point
    expect((await call(page, 'calc_pad_calculate', { expression: '(850 + 120) * 12' })).result).toEqual({ expression: '(850 + 120) * 12', result: 11640 });
    expect((await call(page, 'calc_pad_calculate', { expression: '200 + 10%' })).result.result).toBe(220);
    expect((await call(page, 'calc_pad_calculate', { expression: '2^10 + sqrt(16)' })).result.result).toBe(1028);
    expect((await call(page, 'calc_pad_calculate', { expression: '1.5 * 4' })).result.result).toBe(6);
    // sin 30° = 0.5, sin(π/2) = 1 in radians, d/dx x³ at 2 = 3·2² = 12, ∫₀¹ x² = 1/3
    expect((await call(page, 'calc_pad_calculate', { expression: 'sin 30' })).result.result).toBe(0.5);
    expect((await call(page, 'calc_pad_calculate', { expression: 'sin(pi/2)', angle_unit: 'radians' })).result.result).toBe(1);
    expect((await call(page, 'calc_pad_calculate', { expression: 'derivative(x^3; 2)' })).result.result).toBe(12);
    expect((await call(page, 'calc_pad_calculate', { expression: 'integral(x^2; 0; 1)' })).result.result).toBeCloseTo(1 / 3, 9);
    expect((await call(page, 'calc_pad_calculate', { expression: '1', angle_unit: 'gon' })).ok).toBe(false);
    expect((await call(page, 'calc_pad_calculate', { expression: '1/0' })).error).toContain('not defined');
    expect((await call(page, 'calc_pad_calculate', { expression: 'hello' })).error).toContain('not a complete calculation');
    expect((await call(page, 'calc_pad_calculate', { expression: '' })).ok).toBe(false);
    expect((await call(page, 'calc_pad_calculate', { expression: '1', other: 1 })).ok).toBe(false);
    await expect(page.locator('#pad')).toHaveValue('');
  });

  test('add_lines appends to the open pad and read_pad returns lines with results', async ({ page }) => {
    await page.fill('#pad', 'Miete 850 + 120');
    const a = await call(page, 'calc_pad_add_lines', { text: 'Notiz\n× 12\n' });
    expect(a).toEqual({ ok: true, result: { added: [{ line: 2, text: 'Notiz' }, { line: 3, text: '× 12', result: 11640 }] } });
    await expect(page.locator('#pad')).toHaveValue('Miete 850 + 120\nNotiz\n× 12');
    await expect(page.locator('#mirror .res').last()).toHaveText('11.640');
    await expect(page.locator('#toast')).toHaveText('KI-Agent: Zeilen angehängt');
    const r = (await call(page, 'calc_pad_read_pad', {})).result;
    expect(r).toEqual({
      title: 'Miete 850 + 120', number_format: 'german (1.234,5)', line_count: 3,
      lines: [{ line: 1, text: 'Miete 850 + 120', result: 970 }, { line: 2, text: 'Notiz' }, { line: 3, text: '× 12', result: 11640 }],
    });
    expect((await call(page, 'calc_pad_add_lines', { text: '1/0' })).result.added).toEqual([{ line: 4, text: '1/0', error: 'undefined' }]);
    // A system of equations: 3b + 2c = 0, b + c = -1 → b = 2, c = -3
    expect((await call(page, 'calc_pad_add_lines', { text: '\n3b + 2c = 0\nb + c = -1' })).result.added).toEqual([
      { line: 5, text: '' }, { line: 6, text: '3b + 2c = 0', solutions: [{ name: 'b', value: 2 }] }, { line: 7, text: 'b + c = -1', solutions: [{ name: 'c', value: -3 }] },
    ]);
    expect((await call(page, 'calc_pad_add_lines', { text: '' })).ok).toBe(false);
    expect((await call(page, 'calc_pad_add_lines', { text: 'x'.repeat(5001) })).ok).toBe(false);
    // Quadratic: x² − 5x + 6 = 0 → 2 and 3
    expect((await call(page, 'calc_pad_add_lines', { text: '\nx^2 - 5x + 6 = 0' })).result.added[1]).toEqual(
      { line: 9, text: 'x^2 - 5x + 6 = 0', solutions: [{ name: 'x', value: 2 }, { name: 'x', value: 3 }] });
    // Saved like typed text
    await expect.poll(() => page.evaluate(() => JSON.parse(localStorage.getItem('calc-pad.pads.v1')).pads[0].text)).toBe('Miete 850 + 120\nNotiz\n× 12\n1/0\n\n3b + 2c = 0\nb + c = -1\n\nx^2 - 5x + 6 = 0');
  });
});

test.describe('function-plotter tools', () => {
  test.beforeEach(async ({ page }) => open(page, '/function-plotter/'));

  test('set_functions: lines with errors, parameters, view fitted; shown in the app', async ({ page }) => {
    const r = await call(page, 'function_plotter_set_functions', { functions: ['p x^2 + q', 'f(x) = sin x', "f'(x)", 'x $'], x_min: -2, x_max: 2 });
    expect(r.ok).toBe(true);
    expect(r.result.lines.map(l => l.error ? 'error' : l.name || 'fn')).toEqual(['fn', 'f', 'fn', 'error']);
    expect(r.result.parameters).toEqual({ p: 1, q: 1 });
    expect(r.result.view.x_min).toBe(-2);
    expect(r.result.view.x_max).toBe(2);
    // y fitted to the curves on [−2, 2]: x² + 1 reaches 5, sin and cos reach about ±1
    expect(r.result.view.y_max).toBeGreaterThan(5);
    expect(r.result.view.y_min).toBeLessThan(-0.9);
    await expect(page.locator('#fns input')).toHaveCount(4);
    await expect(page.locator('#fns input').first()).toHaveValue('p x^2 + q');
    await expect(page.locator('#params .param label')).toHaveText(['p', 'q']);
    const bad = await call(page, 'function_plotter_set_functions', { functions: ['x'], x_min: 3, x_max: 1 });
    expect(bad).toEqual({ ok: false, error: 'x_max must be greater than x_min.' });
  });

  test('set_parameter and evaluate: values recomputed independently, zeros and extrema', async ({ page }) => {
    await call(page, 'function_plotter_set_functions', { functions: ['p x^2 - c', 'g = 2', 'g x'], x_min: -3, x_max: 3 });
    let r = await call(page, 'function_plotter_set_parameter', { name: 'c', value: 4, min: 0, max: 10 });
    expect(r).toEqual({ ok: true, result: { name: 'c', value: 4, min: 0, max: 10 } });
    await expect(page.locator('#params .param[data-p="c"] [data-role="v"]')).toHaveValue('4');
    r = await call(page, 'function_plotter_set_parameter', { name: 'z', value: 1 });
    expect(r.ok).toBe(false);
    expect(r.error).toBe('Unknown parameter "z". Parameters: p, c.');
    r = await call(page, 'function_plotter_evaluate', { x: 1.5 });
    expect(r.ok).toBe(true);
    const [l1, l2, l3] = r.result.lines;
    expect(l1.value).toBeCloseTo(1.5 ** 2 - 4, 12);
    expect(l2).toMatchObject({ constant: 'g', value: 2 });
    expect(l3.value).toBeCloseTo(3, 12);
    expect(l1.points.map(p => p.type)).toEqual(['zero', 'min', 'zero']);
    expect(l1.points[0].x).toBeCloseTo(-2, 8);
    expect(l1.points[2].x).toBeCloseTo(2, 8);
    expect(l1.points[1].y).toBeCloseTo(-4, 8);
    // the app shows the values at x = 1,5
    await expect(page.locator('#readoutList li').first()).toHaveText('x = 1,5');
    // not defined → null
    await call(page, 'function_plotter_set_functions', { functions: ['ln x'] });
    r = await call(page, 'function_plotter_evaluate', { x: -1 });
    expect(r.result.lines[0].value).toBeNull();
  });
});

test.describe('video-analysis tools', () => {
  test.use({ locale: 'de-DE' });
  test.beforeEach(async ({ page }) => open(page, '/video-analysis/'));

  test('without a video both tools explain what to do', async ({ page }) => {
    for (const [name, input] of [['video_analysis_get_measurements', {}], ['video_analysis_fit_data', { quantity: 'y', model: 'quad' }]]) {
      expect(await call(page, name, input)).toEqual({ ok: false, error: 'No video is open. Ask the user to open a video in the app.' });
    }
  });

  test('get_measurements and fit_data on tracked points (synthetic fall, see video-analysis.spec.mjs)', async ({ page }) => {
    await page.locator('#fileIn').setInputFiles(new URL('./fixtures/fall.webm', import.meta.url).pathname);
    await expect(page.locator('#frameInfo')).toContainText('Bild 1 von 45');
    const box = await page.locator('#ov').boundingBox(), s = box.width / 320;
    const tap = (x, y) => page.locator('#ov').click({ position: { x: x * s, y: y * s } });
    await page.getByRole('button', { name: 'Maßstab', exact: true }).click();
    await tap(0, 222); await tap(200, 222);
    await page.getByRole('button', { name: 'Punkte', exact: true }).click();
    // centres of the square in frames 0, 1, 2 … (even pixels, see video-analysis.spec.mjs)
    const truth = k => { const t = k / 30; return { x: 2 * Math.floor((52 + 40 * t) / 2) + 8, y: 2 * Math.floor((22 + 60 * t * t) / 2) + 8 }; };
    for (let k = 0; k < 30; k += 1) {
      await expect(page.locator('#frameInfo')).toContainText(`Bild ${k + 1} von 45`);
      await tap(truth(k).x, truth(k).y);
    }
    await expect(page.locator('#tbody tr')).toHaveCount(30);
    let r = await call(page, 'video_analysis_get_measurements', {});
    expect(r.ok).toBe(true);
    expect(r.result.units).toEqual({ position: 'm', velocity: 'm/s' });
    expect(r.result.scale.length_m).toBe(1);
    expect(r.result.scale.pixels).toBeCloseTo(200, 0);
    expect(r.result.frame_rate).toBe(30);
    expect(r.result.points).toHaveLength(30);
    expect(r.result.points[10].t).toBeCloseTo(10 / 30, 9);
    expect(r.result.points[10].x).toBeCloseTo(truth(10).x / 200, 2);
    r = await call(page, 'video_analysis_fit_data', { quantity: 'y', model: 'quad' });
    expect(r.ok).toBe(true);
    // expected: least squares of the true (even-pixel) positions, y = (222 − y_px)/200, computed here with the
    // normal equations of y = c0 + c1·t + c2·t² (Cramer's rule)
    const T = Array.from({ length: 30 }, (_, k) => k / 30), Yv = T.map((_, k) => (222 - truth(k).y) / 200);
    const S = n => T.reduce((a, t) => a + t ** n, 0), SY = n => T.reduce((a, t, i) => a + t ** n * Yv[i], 0);
    const det3 = m => m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1]) - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0]) + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);
    const N = [[S(0), S(1), S(2)], [S(1), S(2), S(3)], [S(2), S(3), S(4)]];
    const c2 = det3(N.map((row, i) => [row[0], row[1], SY(i)])) / det3(N);
    expect(r.result.fit.acceleration).toBeCloseTo(2 * c2, 2);
    expect(Math.abs(2 * c2 + 0.6)).toBeLessThan(0.05);
    expect(r.result.fit.acceleration_error).toBeGreaterThan(0);
    await expect(page.locator('#model')).toHaveValue('quad');
    await expect(page.locator('#fitOut li').nth(1)).toContainText('Beschleunigung');
    r = await call(page, 'video_analysis_fit_data', { quantity: 'x', model: 'lin' });
    expect(Math.abs(r.result.fit.coefficients[1] - 0.2)).toBeLessThan(0.005);
    r = await call(page, 'video_analysis_fit_data', { quantity: 'x', model: 'cubic' });
    expect(r.ok).toBe(false);
  });
});

test.describe('business-card tools', () => {
  test.beforeEach(async ({ page }) => {
    await fakeModelContext(page);
    await page.goto('/business-card/');
  });

  test('get_design reads the card; add_text and update_text change it visibly', async ({ page }) => {
    const d = (await call(page, 'business_card_get_design', {})).result;
    expect(d).toMatchObject({ width_mm: 85, height_mm: 55, orientation: 'landscape', shown_side: 'front', cards_per_a4_page: 10, back_is_printed: true });
    expect(d.sides.front.elements.map(e => e.type)).toEqual(['rect', 'text', 'text', 'line', 'text', 'text']);
    expect(d.sides.back.background).toBe('#0f766e');
    const name = d.sides.front.elements.find(e => e.text === 'Erika Mustermann');
    expect(name).toMatchObject({ size_pt: 13, bold: true, align: 'left' });

    const { ok, result } = await call(page, 'business_card_add_text', { text: 'Termin nach Vereinbarung', side: 'back', size_pt: 7, color: '#FFFFFF' });
    expect(ok).toBe(true);
    // Centred on the card: left + width / 2 = 42.5 mm (rounded to 0.1)
    expect(Math.abs(result.x_mm + result.width_mm / 2 - 42.5)).toBeLessThanOrEqual(0.1);
    expect(result).toMatchObject({ type: 'text', size_pt: 7, color: '#ffffff' });
    await expect(page.locator('input[name="side"][value="back"]')).toBeChecked();
    await expect(page.locator('#pText')).toHaveValue('Termin nach Vereinbarung');
    await expect(page.locator('#toast')).toHaveText('KI-Agent: Text hinzugefügt');

    const upd = await call(page, 'business_card_update_text', { id: name.id, text: 'Dr. Erika Mustermann', size_pt: 12 });
    expect(upd.result).toMatchObject({ text: 'Dr. Erika Mustermann', size_pt: 12, x_mm: name.x_mm });
    await expect(page.locator('input[name="side"][value="front"]')).toBeChecked();
    await expect(page.locator('#elList button', { hasText: 'Dr. Erika Mustermann' })).toHaveAttribute('aria-pressed', 'true');
  });

  test('set_background and wrong input', async ({ page }) => {
    expect((await call(page, 'business_card_set_background', { color: '#112233', side: 'front' })).result).toEqual({ side: 'front', background: '#112233' });
    await expect(page.locator('#bgColor')).toHaveValue('#112233');
    expect(await call(page, 'business_card_set_background', { color: 'blau100' })).toEqual({ ok: false, error: 'color must be a hex colour like #1f2937' });
    expect(await call(page, 'business_card_update_text', { id: 'nope' })).toEqual({ ok: false, error: 'no element with id nope' });
    const line = (await call(page, 'business_card_get_design', {})).result.sides.front.elements.find(e => e.type === 'line');
    expect((await call(page, 'business_card_update_text', { id: line.id, text: 'x' })).error).toBe(`element ${line.id} is a line, not a text`);
    expect((await call(page, 'business_card_add_text', { text: '' })).error).toBe('input.text must have at least 1 characters');
  });
});

test.describe('tic-tac-toe tools', () => {
  test('make_move plays on the board, the computer answers, get_game reads it back', async ({ page }) => {
    await open(page, '/tic-tac-toe/');
    let r = await call(page, 'tic_tac_toe_make_move', { square: 5 });
    expect(r.ok).toBe(true);
    expect(r.result.board[1][1]).toBe('x');
    expect(r.result.to_move).toBe('o');
    await expect(page.locator('#board .cell[data-i="4"]')).toHaveAttribute('data-v', 'x');
    expect((await call(page, 'tic_tac_toe_make_move', { square: 5 })).error).toMatch(/already taken/);
    expect((await call(page, 'tic_tac_toe_make_move', { square: 10 })).ok).toBe(false);
    for (const s of [1, 6, 2, 9]) await call(page, 'tic_tac_toe_make_move', { square: s });
    r = await call(page, 'tic_tac_toe_make_move', { square: 3 });
    expect(r.result.status).toBe('o_wins');
    expect(r.result.winning_line).toEqual([1, 2, 3]);
    expect(r.result.score).toEqual({ x: 0, o: 1, draws: 0 });
    expect((await call(page, 'tic_tac_toe_make_move', { square: 9 })).error).toMatch(/round is over/);
    const g = await call(page, 'tic_tac_toe_get_game', {});
    expect(g.result.status).toBe('o_wins');
    r = await call(page, 'tic_tac_toe_new_round', {});
    expect(r.result.status).toBe('playing');
    expect(r.result.starter).toBe('o');
    expect(r.result.score.o).toBe(1);
  });

  test('against the computer it replies within the same call', async ({ page }) => {
    await page.addInitScript(() => localStorage.setItem('tic-tac-toe.state.v1', JSON.stringify({ opp: 'cpu', level: 'hard' })));
    await open(page, '/tic-tac-toe/');
    const r = await call(page, 'tic_tac_toe_make_move', { square: 1 });
    expect(r.result.opponent).toBe('computer');
    expect(r.result.board[1][1]).toBe('o');
    expect(r.result.to_move).toBe('x');
  });
});

test.describe('four-in-a-row tools', () => {
  test('drop_disc plays on the board, get_game reads it back, full column, win, new_round', async ({ page }) => {
    await open(page, '/four-in-a-row/');
    let r = await call(page, 'four_in_a_row_drop_disc', { column: 4 });
    expect(r.ok).toBe(true);
    expect(r.result.board[5][3]).toBe('red');
    expect(r.result.to_move).toBe('yellow');
    await expect(page.locator('#board .slot[data-i="38"] .disc')).toHaveAttribute('data-v', 'r');
    expect((await call(page, 'four_in_a_row_drop_disc', { column: 8 })).ok).toBe(false);
    for (const c of [4, 4, 4, 4]) await call(page, 'four_in_a_row_drop_disc', { column: c });
    r = await call(page, 'four_in_a_row_drop_disc', { column: 4 });
    expect(r.result.playable_columns).toEqual([1, 2, 3, 5, 6, 7]);
    expect((await call(page, 'four_in_a_row_drop_disc', { column: 4 })).error).toBe('Column 4 is full.');
    // column 4 holds red at the bottom; red 1 2 3 next to it (yellow plays 7) makes four across
    for (const c of [1, 7, 2, 7]) await call(page, 'four_in_a_row_drop_disc', { column: c });
    r = await call(page, 'four_in_a_row_drop_disc', { column: 3 });
    expect(r.result.status).toBe('red_wins');
    expect(r.result.winning_cells).toEqual([1, 2, 3, 4].map(column => ({ row: 6, column })));
    expect(r.result.score).toEqual({ red: 1, yellow: 0, draws: 0 });
    expect((await call(page, 'four_in_a_row_drop_disc', { column: 5 })).error).toMatch(/round is over/);
    expect((await call(page, 'four_in_a_row_get_game', {})).result.status).toBe('red_wins');
    await expect(page.locator('#status')).toHaveText('Rot gewinnt!');
    r = await call(page, 'four_in_a_row_new_round', {});
    expect(r.result).toMatchObject({ status: 'playing', starter: 'yellow', to_move: 'yellow', moves: 0 });
    expect(r.result.score.red).toBe(1);
  });

  test('against the computer it replies within the same call', async ({ page }) => {
    await page.addInitScript(() => localStorage.setItem('four-in-a-row.state.v1', JSON.stringify({ opp: 'cpu', level: 'medium', moves: [0, 6, 1, 6] })));
    await open(page, '/four-in-a-row/');
    const r = await call(page, 'four_in_a_row_drop_disc', { column: 3 });
    expect(r.result.opponent).toBe('computer');
    expect(r.result.board[5][3]).toBe('yellow'); // blocked red 1-2-3
    expect(r.result.to_move).toBe('red');
    expect(r.result.moves).toBe(6);
  });
});

test.describe('chess tools', () => {
  test('two players: make_move takes SAN and UCI, refuses illegal moves, get_game reads the mate', async ({ page }) => {
    await page.addInitScript(() => localStorage.setItem('chess.settings.v1', JSON.stringify({ opp: 'human' })));
    await open(page, '/chess/');
    let r = await call(page, 'chess_get_game', {});
    expect(r.result).toMatchObject({ to_move: 'white', status: 'playing', result: '*', opponent: 'two_players', moves: [] });
    expect(r.result.legal_moves).toHaveLength(20);
    expect(r.result.board[7]).toBe('RNBQKBNR');
    r = await call(page, 'chess_make_move', { move: 'f3' });
    expect(r.result.moves).toEqual(['f3']);
    await expect(page.locator('#board .sq[data-sq="f3"]')).toHaveAttribute('aria-label', 'f3, weißer Bauer');
    expect((await call(page, 'chess_make_move', { move: 'Nf3' })).error).toMatch(/not a legal move/);
    expect((await call(page, 'chess_make_move', { move: 'e2e4extra' })).ok).toBe(false);
    await call(page, 'chess_make_move', { move: 'e7e5' });
    await call(page, 'chess_make_move', { move: 'g4' });
    r = await call(page, 'chess_make_move', { move: 'Qh4' });
    expect(r.result).toMatchObject({ status: 'checkmate', result: '0-1', in_check: true, to_move: null, legal_moves: [], moves: ['f3', 'e5', 'g4', 'Qh4#'] });
    await expect(page.locator('#status')).toHaveText('Schachmatt – Schwarz gewinnt');
    expect((await call(page, 'chess_make_move', { move: 'a3' })).error).toMatch(/game is over/);
    r = await call(page, 'chess_new_game', {});
    expect(r.result).toMatchObject({ status: 'playing', moves: [] });
    await call(page, 'chess_make_move', { move: 'e4' });
    expect((await call(page, 'chess_new_game', {})).error).toMatch(/in progress/);
    await expect(page.locator('#moves li')).toHaveCount(1);
  });

  test('against the computer it answers within the same call; playing black it opens on new_game', async ({ page }) => {
    await page.addInitScript(() => {
      if (!sessionStorage.getItem('seeded')) localStorage.setItem('chess.settings.v1', JSON.stringify({ opp: 'cpu', color: 'w', level: 'easy' }));
      sessionStorage.setItem('seeded', '1');
    });
    await open(page, '/chess/');
    let r = await call(page, 'chess_make_move', { move: 'e2e4' });
    expect(r.result).toMatchObject({ opponent: 'computer', you_play: 'white', computer_level: 'easy', to_move: 'white', computer_thinking: false });
    expect(r.result.moves).toHaveLength(2);
    await expect(page.locator('#moves li')).toHaveCount(2);
    await page.evaluate(() => localStorage.setItem('chess.settings.v1', JSON.stringify({ opp: 'cpu', color: 'b', level: 'easy' })));
    await page.evaluate(() => localStorage.setItem('chess.game.v1', JSON.stringify({ opp: 'cpu', human: 'w', moves: [] })));
    await page.reload();
    r = await call(page, 'chess_new_game', {});
    expect(r.result).toMatchObject({ you_play: 'black', to_move: 'black' });
    expect(r.result.moves).toHaveLength(1);
    expect((await call(page, 'chess_make_move', { move: 'Ke7' })).error).toMatch(/not a legal move/);
  });
});

test.describe('hangman tools', () => {
  const seed = (page, game, extra = {}) => page.addInitScript(([g, e]) => localStorage.setItem('hangman.state.v1',
    JSON.stringify({ mode: 'solo', level: 'medium', ...e, game: g && { lang: 'de', cat: 'animals', source: 'list', lives: 8, guessed: [], ...g } })), [game, extra]);

  test('get_game hides the word, guess_letter plays on the keys, the word shows once it is over', async ({ page }) => {
    await seed(page, { word: 'KÄSE' });
    await open(page, '/hangman/');
    let r = await call(page, 'hangman_get_game', {});
    expect(r.result).toMatchObject({ mode: 'alone', status: 'playing', pattern: '____', letters_in_word: 4, topic: 'animals', word: null, mistakes: 0, max_mistakes: 8 });
    expect(r.result.letters_left_to_try).toHaveLength(29);
    expect(JSON.stringify(r.result)).not.toContain('KÄSE');
    r = await call(page, 'hangman_guess_letter', { letter: 'ä' });
    expect(r.result).toMatchObject({ hit: true, pattern: '_Ä__', right_letters: ['Ä'] });
    await expect(page.locator('#keys .key[data-l="Ä"]')).toHaveAttribute('data-state', 'hit');
    r = await call(page, 'hangman_guess_letter', { letter: 'x' });
    expect(r.result).toMatchObject({ hit: false, wrong_letters: ['X'], mistakes: 1, mistakes_left: 7 });
    await expect(page.locator('#lives')).toHaveText('Fehler 1 von 8');
    expect((await call(page, 'hangman_guess_letter', { letter: 'X' })).error).toMatch(/already guessed/);
    expect((await call(page, 'hangman_guess_letter', { letter: '1' })).ok).toBe(false);
    expect((await call(page, 'hangman_new_game', {})).error).toMatch(/still being guessed/);
    for (const l of 'KS') await call(page, 'hangman_guess_letter', { letter: l });
    r = await call(page, 'hangman_guess_letter', { letter: 'E' });
    expect(r.result).toMatchObject({ status: 'won', word: 'KÄSE', pattern: 'KÄSE' });
    expect(r.result.statistics.won).toBe(1);
    await expect(page.locator('#status')).toHaveText('Gewonnen!');
    expect((await call(page, 'hangman_guess_letter', { letter: 'B' })).error).toMatch(/game is over/);
    r = await call(page, 'hangman_new_game', { topic: 'food' });
    expect(r.result).toMatchObject({ status: 'playing', topic: 'food', word: null, mistakes: 0 });
    await expect(page.locator('#topic')).toHaveText('Thema: Essen');
  });

  test('new_game with a secret word for the user; two-player mode needs a word', async ({ page }) => {
    await seed(page, null, { mode: 'duo' });
    await open(page, '/hangman/');
    let r = await call(page, 'hangman_get_game', {});
    expect(r.result.status).toBe('waiting_for_word');
    expect((await call(page, 'hangman_guess_letter', { letter: 'A' })).error).toMatch(/no word yet/);
    expect((await call(page, 'hangman_new_game', {})).error).toMatch(/two-player mode/);
    expect((await call(page, 'hangman_new_game', { word: 'R2D2' })).error).toMatch(/Only letters/);
    r = await call(page, 'hangman_new_game', { word: 'Eis-bär', hint: 'kalt' });
    expect(r.result).toMatchObject({ status: 'playing', pattern: '___-___', own_word: true, hint: 'kalt', word: null });
    await expect(page.locator('#play')).toBeVisible();
    await expect(page.locator('#topic')).toHaveText('Hinweis: kalt');
  });
});

test.describe('code-breaker tools', () => {
  const seed = (page, game, extra = {}) => page.addInitScript(([g, e]) => localStorage.setItem('code-breaker.state.v1',
    JSON.stringify({ mode: 'solo', level: 'medium', ...e, game: g && { level: 'medium', source: 'random', guesses: [], ...g } })), [game, extra]);

  test('get_game hides the code, make_guess plays on the board, the code shows once cracked', async ({ page }) => {
    await seed(page, { secret: [0, 1, 2, 3] });
    await open(page, '/code-breaker/');
    let r = await call(page, 'code_breaker_get_game', {});
    expect(r.result).toMatchObject({ mode: 'alone', status: 'playing', secret: null, guesses_made: 0, guesses_left: 10, possible_codes_left: 1296 });
    expect(r.result.rules).toMatchObject({ places: 4, colors_may_repeat: true, max_guesses: 10 });
    expect(r.result.rules.colors).toEqual(['red', 'blue', 'green', 'yellow', 'purple', 'orange']);
    r = await call(page, 'code_breaker_make_guess', { code: ['yellow', 'green', 'blue', 'red'] });
    expect(r.result).toMatchObject({ right_place: 0, wrong_place: 4, guesses_made: 1, possible_codes_left: 9 });
    await expect(page.locator('#board li')).toHaveCount(1);
    await expect(page.locator('#board li .pin.white')).toHaveCount(4);
    expect((await call(page, 'code_breaker_make_guess', { code: ['red', 'blue', 'green'] })).error).toMatch(/exactly 4 colours/);
    expect((await call(page, 'code_breaker_make_guess', { code: ['red', 'blue', 'green', 'pink'] })).error).toMatch(/Only these colours/);
    expect((await call(page, 'code_breaker_new_game', {})).error).toMatch(/under way/);
    r = await call(page, 'code_breaker_make_guess', { code: ['red', 'blue', 'green', 'yellow'] });
    expect(r.result).toMatchObject({ status: 'won', right_place: 4, secret: ['red', 'blue', 'green', 'yellow'] });
    expect(r.result.statistics).toMatchObject({ won: 1, tries: 2 });
    await expect(page.locator('#status')).toHaveText('Geknackt in 2 Versuchen!');
    expect((await call(page, 'code_breaker_make_guess', { code: ['red', 'red', 'red', 'red'] })).error).toMatch(/game is over/);
    r = await call(page, 'code_breaker_new_game', {});
    expect(r.result).toMatchObject({ status: 'playing', guesses_made: 0, secret: null });
  });

  test('new_game with a code for the user; two-player mode needs a code', async ({ page }) => {
    await seed(page, null, { mode: 'duo', level: 'easy' });
    await open(page, '/code-breaker/');
    let r = await call(page, 'code_breaker_get_game', {});
    expect(r.result.status).toBe('waiting_for_code');
    expect((await call(page, 'code_breaker_make_guess', { code: ['red', 'blue', 'green', 'yellow'] })).error).toMatch(/no code yet/);
    expect((await call(page, 'code_breaker_new_game', {})).error).toMatch(/two-player mode/);
    expect((await call(page, 'code_breaker_new_game', { code: ['red', 'red', 'green', 'yellow'] })).error).toMatch(/only once/);
    r = await call(page, 'code_breaker_new_game', { code: ['orange', 'red', 'green', 'yellow'] });
    expect(r.result).toMatchObject({ status: 'playing', own_code: true, secret: null, difficulty: 'easy' });
    await expect(page.locator('#board')).toBeVisible();
    await expect(page.locator('#secretLine')).toHaveAttribute('aria-label', 'Geheimer Code mit 4 Farben');
  });
});

test.describe('dots-and-boxes tools', () => {
  test('make_move draws lines, a closed box moves again, get_game reads it back, new_round', async ({ page }) => {
    await open(page, '/dots-and-boxes/');
    let r = await call(page, 'dots_and_boxes_get_game', {});
    expect(r.result).toMatchObject({ size: 4, status: 'playing', to_move: 'a', lines_drawn: 0, opponent: 'two_players' });
    expect(r.result.free_lines).toHaveLength(40);
    for (const line of ['A1-B1', 'A1-A2', 'B1-B2']) r = await call(page, 'dots_and_boxes_make_move', { line });
    expect(r.result.to_move).toBe('b');
    await expect(page.locator('#board .edge[data-line="B1-B2"]')).toBeDisabled();
    r = await call(page, 'dots_and_boxes_make_move', { line: 'b2-a2' });
    expect(r.result.boxes[0][0]).toBe('b');
    expect(r.result.to_move).toBe('b');
    expect(r.result.boxes_won).toEqual({ a: 0, b: 1 });
    expect(r.result.last_turn).toEqual(['A2-B2']);
    await expect(page.locator('#ptsB')).toHaveText('1');
    expect((await call(page, 'dots_and_boxes_make_move', { line: 'A1-B1' })).error).toMatch(/already drawn/);
    expect((await call(page, 'dots_and_boxes_make_move', { line: 'A1-B2' })).error).toMatch(/not a line/);
    expect((await call(page, 'dots_and_boxes_make_move', { line: 'A1-F1' })).error).toMatch(/not a line/);
    expect((await call(page, 'dots_and_boxes_make_move', { line: 'nope' })).ok).toBe(false);
    r = await call(page, 'dots_and_boxes_new_round', {});
    expect(r.result).toMatchObject({ status: 'playing', starter: 'b', to_move: 'b', lines_drawn: 0 });
  });

  test('against the computer it plays its whole turn within the same call', async ({ page }) => {
    await page.addInitScript(() => localStorage.setItem('dots-and-boxes.state.v1', JSON.stringify({ opp: 'cpu', level: 'medium', n: 3, size: 3 })));
    await open(page, '/dots-and-boxes/');
    let r = await call(page, 'dots_and_boxes_make_move', { line: 'A1-B1' });
    expect(r.result).toMatchObject({ opponent: 'computer', computer_level: 'medium', to_move: 'a', lines_drawn: 2 });
    // Play until the end: the agent always takes the first free line
    while (r.result.status === 'playing') r = await call(page, 'dots_and_boxes_make_move', { line: r.result.free_lines[0] });
    expect(r.result.free_lines).toEqual([]);
    expect(r.result.boxes_won.a + r.result.boxes_won.b).toBe(9);
    expect((await call(page, 'dots_and_boxes_make_move', { line: 'A1-B1' })).error).toMatch(/round is over/);
    await expect(page.locator('#btnNext')).toBeVisible();
  });
});

test.describe('playlist-player tools', () => {
  // Fake YouTube (routed; the service worker would pass requests past the routes)
  test.use({ serviceWorkers: 'block', allowedProblems: /^external request: https:\/\/www\.youtube-nocookie\.com\/(embed\/|oembed\?)/ });

  test('nothing chosen → errors; control only after the user tapped Play; progress, speed', async ({ page }) => {
    await fakeYoutube(page);
    await open(page, '/playlist-player/');
    expect((await call(page, 'playlist_player_get_progress', {})).error).toMatch(/No playlist chosen/);
    await page.locator('#inUrl').fill(`https://youtube.com/playlist?list=${LIST}`);
    await page.getByRole('button', { name: 'Öffnen' }).click();
    await expect(page.locator('#listName')).toHaveText(LIST_TITLE);
    // An agent cannot start the player (that loads YouTube) – only the person can
    let r = await call(page, 'playlist_player_control', { action: 'play' });
    expect(r.error).toMatch(/user has to tap Play/);
    await expect(page.locator('#slot iframe')).toHaveCount(0);
    r = await call(page, 'playlist_player_set_speed', { rate: 1.75 });
    expect(r.result).toEqual({ speed: 1.75 });
    await expect(page.locator('#selRate')).toHaveValue('1.75');
    expect((await call(page, 'playlist_player_set_speed', { rate: 3 })).error).toMatch(/must be one of/);

    await page.locator('#btnStart').click();
    const frame = await playerFrame(page);
    await expect(page.locator('#tracks .track')).toHaveCount(3);
    await expect.poll(() => frame.evaluate(() => window.fake.state().rate)).toBe(1.75);
    await frame.evaluate(() => window.fake.advance(120));
    await expect(page.locator('#tracks .track').nth(1)).toHaveClass(/current/);
    r = await call(page, 'playlist_player_control', { action: 'pause' });
    expect(r.result).toEqual({ action: 'pause', current_part: 2, part_count: 3 });
    await expect(page.locator('#btnPlay')).toHaveAttribute('aria-label', 'Abspielen');
    r = await call(page, 'playlist_player_control', { action: 'next' });
    await expect(page.locator('#tracks .track').nth(2)).toHaveClass(/current/);
    expect((await call(page, 'playlist_player_control', { action: 'rewind' })).error).toMatch(/must be one of/);

    const { ok, result } = await call(page, 'playlist_player_get_progress', { limit: 2 });
    expect(ok).toBe(true);
    expect(result).toMatchObject({ playlist: LIST_TITLE, part_count: 3, heard_count: 1, current_part: 3, player_started: true, speed: 1.75 });
    expect(result.parts).toHaveLength(2);
    expect(result.parts[0]).toMatchObject({ number: 1, title: VIDEOS[0].title, channel: VIDEOS[0].author, duration_seconds: 120, heard: true });
    expect(Date.parse(result.parts[0].heard_at)).toBeGreaterThan(Date.now() - 60e3);
    expect(result.parts[1]).toMatchObject({ number: 2, title: VIDEOS[1].title, heard: false });
    const tools = await listTools(page);
    expect(tools.find(t => t.name === 'playlist_player_get_progress').annotations).toEqual({ readOnlyHint: true, untrustedContentHint: true });
    expect(tools.find(t => t.name === 'playlist_player_control').annotations.readOnlyHint).toBe(false);
  });
});

test.describe('rss-reader tools', () => {
  test.use({ allowedProblems: FEED_PROBLEMS });

  test('list_feeds, list_items (filters, paging, plain text) and select_feed – never fetch', async ({ page }) => {
    const seen = await mockFeeds(page);
    await fakeModelContext(page);
    await page.goto('/rss-reader/');
    // First feed on the start screen, the second via menu → "Feed hinzufügen"
    await page.fill('#feedUrl', `${FEED_ORIGIN}/rss.xml`);
    await page.click('#btnAdd');
    await expect(page.locator('#status')).toContainText('3 Einträge');
    await openMenu(page);
    await page.click('#btnNew');
    await page.fill('#feedUrl', `${FEED_ORIGIN}/atom.xml`);
    await page.click('#btnAdd');
    await expect(page.locator('#status')).toContainText('2 Einträge');
    expect(seen).toHaveLength(2);

    let r = await call(page, 'rss_reader_list_feeds', {});
    expect(r.result.current).toBe(r.result.feeds[1].id);
    expect(r.result.feeds.map(f => [f.name, f.url, f.entries, f.unread])).toEqual([
      ['Roadmap Test', `${FEED_ORIGIN}/rss.xml`, 3, 3], ['Atom Blog', `${FEED_ORIGIN}/atom.xml`, 2, 2]]);
    const [rss, atom] = r.result.feeds.map(f => f.id);

    // Default: the feed shown in the app
    r = await call(page, 'rss_reader_list_items', {});
    expect(r.result.items.map(i => i.title)).toEqual(['Erster & bester Beitrag', 'Zweiter Beitrag']);
    r = await call(page, 'rss_reader_list_items', { feed_id: rss, category: 'Outlook', limit: 1 });
    expect(r.result).toMatchObject({ feed_id: rss, total: 2, offset: 0 });
    expect(r.result.items).toEqual([{ id: '1002', feed_id: rss, title: 'Outlook: Ordner teilen', link: `${FEED_ORIGIN}/roadmap?id=1002`,
      date: '2026-11-13T09:00:00.000Z', categories: ['Rolling out', 'Outlook'], read: false, summary: 'Ordner lassen sich teilen.' }]);
    r = await call(page, 'rss_reader_list_items', { feed_id: rss, category: 'Outlook', limit: 1, offset: 1 });
    expect(r.result.items.map(i => i.id)).toEqual(['1003']);
    // Summary is plain text: no markup, scripts dropped, image as alt text
    r = await call(page, 'rss_reader_list_items', { feed_id: 'all', query: 'ansicht' });
    expect(r.result.items).toHaveLength(1);
    expect(r.result.items[0].summary).toBe('Eine neue Ansicht. [Bild] böser Link Details');
    expect((await call(page, 'rss_reader_list_items', { feed_id: 'nope' })).error).toMatch(/Unknown feed_id/);
    expect((await call(page, 'rss_reader_list_items', { limit: 51 })).error).toMatch(/limit/);

    // Read state follows the app
    await page.locator('#items .item summary').first().click();
    await expect(page.locator('#items .item').first()).not.toHaveClass(/unread/);
    r = await call(page, 'rss_reader_list_items', { unread_only: true });
    expect(r.result.items.map(i => i.title)).toEqual(['Zweiter Beitrag']);

    // select_feed switches the view
    r = await call(page, 'rss_reader_select_feed', { feed_id: rss });
    expect(r.result.feed).toMatchObject({ id: rss, name: 'Roadmap Test', unread: 3 });
    await expect(page.locator('#feedSel')).toHaveValue(rss);
    await expect(page.locator('#items .item')).toHaveCount(3);
    await call(page, 'rss_reader_select_feed', { feed_id: 'all' });
    await expect(page.locator('#feedSel')).toHaveValue('all');
    await expect(page.locator('#items .item')).toHaveCount(5);
    expect((await call(page, 'rss_reader_select_feed', { feed_id: 'nope' })).error).toMatch(/Unknown feed_id/);
    expect(atom).toBeTruthy();
    // Agents never fetch
    expect(seen).toHaveLength(2);

    const tools = await listTools(page);
    expect(tools.find(t => t.name === 'rss_reader_list_items').annotations).toEqual({ readOnlyHint: true, untrustedContentHint: true });
    expect(tools.find(t => t.name === 'rss_reader_select_feed').annotations.readOnlyHint).toBe(false);
  });
});

