test.describe('finance-calculator tools', () => {
  test.use({ locale: 'de-DE' });
  test.beforeEach(async ({ page }) => open(page, '/finance-calculator/'));

  test('savings_plan fills the savings calculator and returns the result', async ({ page }) => {
    const r = await call(page, 'finance_calculator_savings_plan', { start_capital: 1000, monthly_contribution: 100, annual_return_percent: 6, years: 10, contribution_at: 'end_of_month' });
    expect(r.ok).toBe(true);
    const q = Math.pow(1.06, 1 / 12) - 1;
    const cap = 1000 * Math.pow(1 + q, 120) + 100 * (Math.pow(1 + q, 120) - 1) / q;
    expect(r.result.final_capital).toBeCloseTo(cap, 1);
    expect(r.result.paid_in).toBe(13000);
    await expect(page.locator('[data-key="s.rate"]')).toHaveValue('100');
    await expect(page.locator('#tab-save')).toHaveAttribute('aria-selected', 'true');
    // contribution needed: same plan backwards
    const back = await call(page, 'finance_calculator_savings_plan', { solve_for: 'monthly_contribution', start_capital: 1000, target_capital: cap, annual_return_percent: 6, years: 10, contribution_at: 'end_of_month' });
    expect(back.result.monthly_contribution).toBeCloseTo(100, 2);
    expect((await call(page, 'finance_calculator_savings_plan', { start_capital: 1000, annual_return_percent: 6, years: 10 })).error).toContain('monthly_contribution');
    expect((await call(page, 'finance_calculator_savings_plan', { solve_for: 'duration', start_capital: 0, monthly_contribution: 0, target_capital: 10, annual_return_percent: 0 })).error).toContain('100 years');
  });

  test('loan: payment, remaining debt after the fixed period, one of three inputs', async ({ page }) => {
    const r = await call(page, 'finance_calculator_loan', { amount: 300000, interest_percent: 3.5, initial_repayment_percent: 2, fixed_rate_years: 10 });
    const i = 0.035 / 12, R = 1375, bal = 300000 * Math.pow(1 + i, 120) - R * (Math.pow(1 + i, 120) - 1) / i;
    expect(r.result.monthly_payment).toBe(R);
    expect(r.result.remaining_debt_after_fixed_period).toBeCloseTo(bal, 1);
    await expect(page.locator('#tab-loan')).toHaveAttribute('aria-selected', 'true');
    await expect(page.locator('[data-key="l.rate"]')).toHaveValue('3,5');
    expect((await call(page, 'finance_calculator_loan', { amount: 1000, interest_percent: 3, years: 5, monthly_payment: 20 })).error).toContain('exactly one');
    expect((await call(page, 'finance_calculator_loan', { amount: 300000, interest_percent: 4, monthly_payment: 900 })).error).toContain('does not cover');
  });

  test('time_value solves any of the five values', async ({ page }) => {
    const r = await call(page, 'finance_calculator_time_value', { solve_for: 'pmt', n: 360, rate_percent: 6, pv: 200000, fv: 0 });
    const i = 0.005;
    expect(r.result.pmt).toBeCloseTo(-200000 * i / (1 - Math.pow(1 + i, -360)), 2);
    await expect(page.locator('#tMsg')).toContainText('PMT = -1.199,10');
    const rate = await call(page, 'finance_calculator_time_value', { solve_for: 'rate_percent', n: 10, pv: -10000, pmt: 0, fv: 20000, payments_per_year: 1 });
    expect(rate.result.rate_percent).toBeCloseTo((Math.pow(2, 0.1) - 1) * 100, 5);
    expect((await call(page, 'finance_calculator_time_value', { solve_for: 'rate_percent', n: 10, pv: 10000, pmt: 0, fv: 20000 })).error).toContain('signs');
    expect((await call(page, 'finance_calculator_time_value', { solve_for: 'fv', n: 10, pv: 1 })).error).toContain('is needed');
  });

  test('cash_flows and convert_rate', async ({ page }) => {
    const r = await call(page, 'finance_calculator_cash_flows', { cf0: -1000, flows: [{ amount: 600 }, { amount: 600 }], rate_percent: 10 });
    expect(r.result.npv).toBeCloseTo(-1000 + 600 / 1.1 + 600 / 1.21, 2);
    // −1000 + 600/(1+r) + 600/(1+r)² = 0 → 1+r = (600 + √(600² + 4·1000·600)) / 2000
    expect(r.result.irr_percent).toBeCloseTo(((600 + Math.sqrt(600 ** 2 + 4 * 1000 * 600)) / 2000 - 1) * 100, 4);
    await expect(page.locator('#cfRows input[data-f="cf"]')).toHaveCount(2);
    const c = await call(page, 'finance_calculator_convert_rate', { given: 'nominal', rate_percent: 6, compounding_per_year: 12 });
    expect(c.result.effective_percent).toBeCloseTo((Math.pow(1.005, 12) - 1) * 100, 5);
    await expect(page.locator('#tab-iconv')).toHaveAttribute('aria-selected', 'true');
  });
});

test.describe('unit-converter tools', () => {
  test.use({ locale: 'de-DE' });
  test.beforeEach(async ({ page }) => open(page, '/unit-converter/'));

  test('convert_unit by id or symbol opens the converter with the values', async ({ page }) => {
    const r = await call(page, 'unit_converter_convert_unit', { value: 100, from: '°C', to: 'degF' });
    expect(r.ok).toBe(true);
    expect(r.result).toMatchObject({ quantity: 'temperature', result: 212, from: { id: 'degC', symbol: '°C', si: true }, to: { id: 'degF', si: false } });
    await expect(page.locator('#p-temperature')).toBeVisible();
    await expect(page.locator('#p-temperature .calc-result.main .v')).toHaveText('212 °F');
    // 1 mile = 1.609344 km exactly; psi by symbol; "rad" needs the quantity to tell angle from dose
    expect((await call(page, 'unit_converter_convert_unit', { value: 1, from: 'mi', to: 'km' })).result.result).toBe(1.609344);
    expect((await call(page, 'unit_converter_convert_unit', { value: 1, from: 'bar', to: 'psi' })).result.result).toBeCloseTo(1e5 / (0.45359237 * 9.80665 / 0.0254 ** 2), 9);
    expect((await call(page, 'unit_converter_convert_unit', { value: Math.PI, from: 'rad', to: 'deg', quantity: 'angle' })).result.result).toBeCloseTo(180, 9);
    expect((await call(page, 'unit_converter_convert_unit', { value: 1, from: 'kg', to: 'm' })).error).toContain('different quantities');
    expect((await call(page, 'unit_converter_convert_unit', { value: 1, from: 'furlong', to: 'm' })).error).toContain('Unknown unit');
    expect((await call(page, 'unit_converter_convert_unit', { value: 0, from: 'l100km', to: 'mpgUS' })).ok).toBe(false);
  });

  test('list_units lists quantities and units, read only', async ({ page }) => {
    const tools = await listTools(page);
    expect(tools.find(t => t.name === 'unit_converter_list_units').annotations.readOnlyHint).toBe(true);
    const all = (await call(page, 'unit_converter_list_units', {})).result;
    expect(all.quantities).toHaveLength(34);
    expect(all.quantities.find(q => q.id === 'length').units).toContain('ft');
    const p = (await call(page, 'unit_converter_list_units', { quantity: 'pressure' })).result;
    expect(p.si_unit).toBe('Pa');
    expect(p.units.find(u => u.id === 'psi')).toEqual({ id: 'psi', symbol: 'psi', name: 'pound-force per square inch', si: false });
  });
});

test.describe('face-timelapse tools', () => {
  test.use({ reducedMotion: 'reduce' });
  test.beforeEach(async ({ page }) => {
    await fakeFaceWorker(page);
    await onDialog(page, d => d.accept());
    await open(page, '/face-timelapse/');
    const eyes = [[160, 120], [240, 120]];
    await page.setInputFiles('#inPick', [
      { name: 'new.png', mimeType: 'image/png', buffer: await facePhoto(page, { eyes }) },
      { name: 'old.jpg', mimeType: 'image/jpeg', buffer: withExifDate(await facePhoto(page, { eyes, type: 'image/jpeg' }), '2018:06:01 12:00:00') },
      { name: 'none.png', mimeType: 'image/png', buffer: await facePhoto(page) },
    ]);
    await expect(page.locator('#addInfo')).toHaveText('3 Foto(s) hinzugefügt.');
  });
  const order = page => page.evaluate(() => [...document.querySelectorAll('#photos li')].map(li => li.dataset.id).join(','));

  test('list_photos reads photos and options without changing anything', async ({ page }) => {
    const r = (await call(page, 'face_timelapse_list_photos', {})).result;
    expect(r).toMatchObject({ count: 3, usable: 2, options: { format: 'square', face_width: 55, seconds_per_photo: 0.5, crossfade: true, show_date: false, output: 'video', size: 720 } });
    expect(r.photos.map(p => [p.position, p.face, p.faces_found, p.date_source])).toEqual([[1, 'found', 1, 'file'], [2, 'found', 1, 'exif'], [3, 'none', 0, 'file']]);
    expect(r.photos[1].date).toBe(await page.evaluate(() => new Date(2018, 5, 1, 12).toISOString()));
    // No file names (user content) in the result
    expect(JSON.stringify(r)).not.toMatch(/new|old|none\.png/);
    expect(await order(page)).toBe('1,2,3');
  });

  test('move_photo and sort_photos change the order shown in the app', async ({ page }) => {
    let r = await call(page, 'face_timelapse_move_photo', { from: 3, to: 1 });
    expect(r.result.photos.map(p => p.face)).toEqual(['none', 'found', 'found']);
    await expect.poll(() => order(page)).toBe('3,1,2');
    await expect(page.locator('.toast')).toContainText('KI-Agent: Foto verschoben');
    // Expected order from the dates the tool reports (stable for equal dates): 2018 (EXIF) first, then the file dates
    const ids = (await order(page)).split(',');
    const expected = r.result.photos.map((p, i) => [Date.parse(p.date), i, ids[i]]).sort((a, b) => a[0] - b[0] || a[1] - b[1]).map(x => x[2]).join(',');
    expect(expected.startsWith('2,')).toBe(true);
    r = await call(page, 'face_timelapse_sort_photos', { by: 'date' });
    expect(r.result.photos.map(p => p.date_source)).toEqual(['exif', 'file', 'file']);
    await expect.poll(() => order(page)).toBe(expected);
    await call(page, 'face_timelapse_sort_photos', { by: 'reverse' });
    await expect.poll(() => order(page)).toBe(expected.split(',').reverse().join(','));
  });

  test('set_options changes only the given options, shown and saved in the app', async ({ page }) => {
    const r = await call(page, 'face_timelapse_set_options', { format: 'story', face_width: 72, seconds_per_photo: 1.24, output: 'gif', show_date: true });
    expect(r.result).toEqual({ format: 'story', face_width: 70, seconds_per_photo: 1.2, crossfade: true, show_date: true, output: 'gif', size: 720 });
    await expect(page.locator('input[name="format"][value="story"]')).toBeChecked();
    await expect(page.locator('#faceOut')).toHaveText('70 %');
    await expect(page.locator('#secsOut')).toHaveText('1,2 s');
    await expect(page.locator('#optDate')).toBeChecked();
    await expect(page.locator('#saveLabel')).toHaveText('GIF speichern');
    // 1.2 s for the first photo, the last one stays 1.2 s too (at least 1 s)
    await expect(page.locator('#exportHintText')).toHaveText('2 Fotos · 2,4 s · 720 × 1280 px');
    expect(await page.evaluate(() => JSON.parse(localStorage.getItem('face-timelapse.settings.v1')))).toMatchObject({ format: 'story', face: 70, secs: 1.2, out: 'gif', date: true });
  });

  test('invalid input is rejected and changes nothing', async ({ page }) => {
    for (const [name, input, msg] of [
      ['face_timelapse_move_photo', { from: 1, to: 4 }, /only 3 photos/],
      ['face_timelapse_move_photo', { from: 0, to: 1 }, />= 1/],
      ['face_timelapse_move_photo', { from: 1 }, /required/],
      ['face_timelapse_sort_photos', { by: 'name' }, /one of/],
      ['face_timelapse_set_options', { size: 600 }, /one of/],
      ['face_timelapse_set_options', { face_width: 120 }, /<= 100/],
      ['face_timelapse_set_options', { seconds_per_photo: 0 }, />= 0.1/],
      ['face_timelapse_set_options', { speed: 2 }, /not allowed/],
    ]) expect((await call(page, name, input)).error, name).toMatch(msg);
    expect(await order(page)).toBe('1,2,3');
    expect((await call(page, 'face_timelapse_list_photos', {})).result.options).toMatchObject({ size: 720, face_width: 55, seconds_per_photo: 0.5 });
  });
});

test.describe('collage-maker tools', () => {
  // Two one-colour photos (landscape 2:1 and square), drawn in the browser
  test.beforeEach(async ({ page }) => {
    await open(page, '/collage-maker/');
    const files = await page.evaluate(() => [[200, 100, '#f00'], [120, 120, '#00f']].map(([w, h, c]) => {
      const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
      const g = cv.getContext('2d'); g.fillStyle = c; g.fillRect(0, 0, w, h);
      return cv.toDataURL('image/png').split(',')[1];
    }));
    await page.setInputFiles('#inPick', files.map((b, i) => ({ name: `p${i}.png`, mimeType: 'image/png', buffer: Buffer.from(b, 'base64') })));
    await expect(page.locator('#collage > button')).toHaveCount(2);
  });

  test('get_collage, set_layout and set_export; changes appear in the app', async ({ page }) => {
    let r = await call(page, 'collage_maker_get_collage', {});
    expect(r.result).toMatchObject({ images: 2, mode: 'auto', aspect: 'free', gap_percent: 0, background: '#ffffff', export: { size: 'full', format: 'jpg' } });
    expect(r.result.max_crop_percent).toBe(0);
    // Free: side by side gives 3:1 (too wide), stacked 2:3 – the app takes the stacked one, nothing cropped
    expect(r.result.cells.map(c => c.image).sort()).toEqual([1, 2]);
    expect(JSON.stringify(r.result)).not.toContain('p0.png');

    r = await call(page, 'collage_maker_set_layout', { mode: 'rows', aspect: '1:1', gap_percent: 1, background: '#00FF00' });
    expect(r.result).toMatchObject({ mode: 'rows', aspect: '1:1', gap_percent: 1, background: '#00ff00' });
    await expect(page.locator('.toast')).toContainText('KI-Agent: Anordnung geändert');
    await expect(page.locator('#mode [data-mode="rows"]')).toHaveAttribute('aria-pressed', 'true');
    await expect(page.locator('#aspect [data-aspect="1:1"]')).toHaveAttribute('aria-pressed', 'true');
    await expect(page.locator('#gapOut')).toHaveText('1,0 %');
    expect(r.result.export.width).toBe(r.result.export.height);
    // Gap 1 % of the side: first cell starts there
    expect(r.result.cells[0].x).toBe(Math.round(r.result.export.width * 0.01));

    r = await call(page, 'collage_maker_set_export', { size: '4000', format: 'png' });
    expect(r.result.export).toMatchObject({ size: '4000', format: 'png', width: 4000, height: 4000, megapixels: 16 });
    await expect(page.locator('#format [data-format="png"]')).toHaveAttribute('aria-pressed', 'true');
    await expect(page.locator('#exportInfo')).toHaveText('Ergebnis: 4.000 × 4.000 Pixel (16 Megapixel)');

    // Rearranged: the photos change places (numbers follow the new order, so compare the cell shapes)
    const shapes = cells => cells.map(c => `${c.width}x${c.height}`).join();
    const before = shapes((await call(page, 'collage_maker_get_collage', {})).result.cells);
    let changed = false;
    for (let i = 0; i < 10 && !changed; i++) {
      r = await call(page, 'collage_maker_set_layout', { rearrange: true });
      changed = shapes(r.result.cells) !== before;
    }
    expect(changed).toBe(true);
  });

  test('wrong input is rejected', async ({ page }) => {
    for (const [input, msg] of [
      [{ mode: 'grid' }, /mode/], [{ gap_percent: 5 }, /gap_percent/], [{ background: 'red' }, /background/],
      [{ background: '#12345g' }, /background/], [{ extra: 1 }, /not allowed/],
    ]) expect((await call(page, 'collage_maker_set_layout', input)).error).toMatch(msg);
    expect((await call(page, 'collage_maker_set_export', { size: '3000' })).error).toMatch(/size/);
    expect((await call(page, 'collage_maker_get_collage', {})).result).toMatchObject({ mode: 'auto', gap_percent: 0, background: '#ffffff' });
  });
});

test.describe('tournament tools', () => {
  test.beforeEach(async ({ page }) => {
    await fakeModelContext(page);
    await page.goto('/tournament/');
  });

  test('get_tournament and set_result: read the schedule, enter a score, the table follows', async ({ page }) => {
    // Nothing running yet: the players and the chosen format
    expect(await call(page, 'tournament_set_result', { match: 1, scoreA: 1, scoreB: 0 }))
      .toEqual({ ok: false, error: 'No tournament is running. The user has to start one first.' });
    await page.fill('#nameIn', 'Ann, Bob, Cy');
    await page.click('#addForm button[type=submit]');
    await page.locator('#size [data-size="1"]').click();
    await page.uncheck('#optRandom');
    expect((await call(page, 'tournament_get_tournament', {})).result)
      .toEqual({ running: false, players: ['Ann', 'Bob', 'Cy'], teamSize: 1, format: 'rr' });
    await page.click('#btnStart');

    const { result } = await call(page, 'tournament_get_tournament', {});
    expect(result.format).toBe('round_robin');
    expect(result.teams).toEqual([{ name: 'Ann', members: ['Ann'] }, { name: 'Bob', members: ['Bob'] }, { name: 'Cy', members: ['Cy'] }]);
    expect(result.matches[0]).toEqual({ match: 1, round: 1, teamA: 'Bob', teamB: 'Cy', score: null });
    expect(result.winner).toBeNull();

    const set = await call(page, 'tournament_set_result', { match: 1, scoreA: 10, scoreB: 7 });
    expect(set.ok).toBe(true);
    expect(set.result.match).toBe(1);
    expect(set.result.tournament.matches[0].score).toEqual({ teamA: 10, teamB: 7 });
    expect(set.result.tournament.table[0]).toEqual({ place: 1, team: 'Bob', played: 1, won: 1, drawn: 0, lost: 0, goalsFor: 10, goalsAgainst: 7, points: 3 });
    await expect(page.locator('#games button.game[data-no="1"] .res')).toHaveText('10 : 7');
    await expect(page.locator('#toast')).toHaveText('KI-Agent: Ergebnis eingetragen');

    expect(await call(page, 'tournament_set_result', { match: 9, scoreA: 1, scoreB: 0 })).toEqual({ ok: false, error: 'There is no match 9.' });
    expect((await call(page, 'tournament_set_result', { match: 1, scoreA: -1, scoreB: 0 })).ok).toBe(false);
  });

  test('set_result in a knockout: no draws, unknown teams refused', async ({ page }) => {
    await page.fill('#nameIn', 'A, B, C');
    await page.click('#addForm button[type=submit]');
    await page.locator('#size [data-size="1"]').click();
    await page.locator('input[name=mode][value="ko"]').check();
    await page.click('#btnStart');
    expect(await call(page, 'tournament_set_result', { match: 1, scoreA: 3, scoreB: 3 }))
      .toEqual({ ok: false, error: 'A knockout match needs a winner; a draw is not allowed.' });
    expect(await call(page, 'tournament_set_result', { match: 2, scoreA: 3, scoreB: 1 }))
      .toEqual({ ok: false, error: 'The teams of match 2 are not known yet.' });
    expect((await call(page, 'tournament_set_result', { match: 1, scoreA: 3, scoreB: 1 })).ok).toBe(true);
    const { result } = await call(page, 'tournament_set_result', { match: 2, scoreA: 0, scoreB: 2 });
    expect(result.tournament.winner).toBe(result.tournament.matches[1].teamB);
    await expect(page.locator('#champName')).toHaveText(result.tournament.winner);
  });
});

test.describe('quantum-magnetism tools', () => {
  test.use({ reducedMotion: 'reduce' });
  test.beforeEach(async ({ page }) => open(page, '/quantum-magnetism/'));

  test('set_classical and run_sweeps: settings shown in the app, exact values, ordered ferromagnet stays ordered', async ({ page }) => {
    let r = await call(page, 'quantum_magnetism_set_classical', { lattice: 'square', coupling: 'ferro', temperature: 0.5, field: 0, size: 'small', start: 'ordered' });
    expect(r.ok).toBe(true);
    expect(r.result.settings).toEqual({ lattice: 'square', coupling: 'ferro', temperature: 0.5, field: 0, size: 'small', sites: 144, sweeps: 0 });
    // Onsager: Tc = 2 / ln(1 + √2)
    expect(r.result.exact).toEqual({ critical_temperature: Math.round(2 / Math.log(1 + Math.SQRT2) * 1e4) / 1e4, ground_energy_per_spin: -2, residual_entropy_per_spin: 0 });
    expect(r.result.measurements).toEqual({ magnetization: 1, staggered_order: 0, energy_per_spin: -2, frustrated_bonds: 0 });
    await expect(page.locator('#size [data-v="0"]')).toHaveAttribute('aria-pressed', 'true');
    await expect(page.locator('#oT')).toHaveText('0,50');
    r = await call(page, 'quantum_magnetism_run_sweeps', { sweeps: 50 });
    expect(r.ok).toBe(true);
    expect(r.result.settings.sweeps).toBe(50);
    expect(r.result.averages.abs_magnetization).toBeGreaterThan(0.99);
    expect(r.result.averages.energy_per_spin).toBeLessThan(-1.98);
    await expect(page.locator('#badge')).toContainText('Durchlauf 50');
    const bad = await call(page, 'quantum_magnetism_set_classical', { temperature: 9 });
    expect(bad).toEqual({ ok: false, error: 'input.temperature must be <= 6' });
    expect((await call(page, 'quantum_magnetism_run_sweeps', {})).ok).toBe(false);
  });

  test('set_classical on the frustrated triangular antiferromagnet; get_classical reads it without changes', async ({ page }) => {
    const r = await call(page, 'quantum_magnetism_set_classical', { lattice: 'triangular', coupling: 'antiferro', size: 'small', start: 'ordered' });
    // Two up, one down per triangle: a third of all bonds unhappy, energy −3 + 2 = −1 per spin
    expect(r.result.measurements).toEqual({ magnetization: 0.3333, staggered_order: 1, energy_per_spin: -1, frustrated_bonds: 0.3333 });
    expect(r.result.exact).toEqual({ critical_temperature: null, ground_energy_per_spin: -1, residual_entropy_per_spin: 0.3383 });
    await expect(page.locator('#coupling [data-v="-1"]')).toHaveAttribute('aria-pressed', 'true');
    const g = await call(page, 'quantum_magnetism_get_classical', {});
    expect(g.result.settings.lattice).toBe('triangular');
    expect(g.result.measurements).toEqual(r.result.measurements);
    expect(g.result.temperature_scan).toBe(null);
    const tools = await listTools(page);
    expect(tools.find(t => t.name === 'quantum_magnetism_get_classical').annotations.readOnlyHint).toBe(true);
  });

  test('get_classical returns the points of a finished temperature scan', async ({ page }) => {
    await call(page, 'quantum_magnetism_set_classical', { lattice: 'square', coupling: 'ferro', field: 0, size: 'small' });
    await page.click('#btnScan');
    await expect(page.locator('#btnScan')).toHaveAttribute('aria-pressed', 'false', { timeout: 60000 });
    const { result } = await call(page, 'quantum_magnetism_get_classical', {});
    const pts = result.temperature_scan.points;
    expect(pts).toHaveLength(30);
    expect(pts[0].temperature).toBe(4);
    expect(pts[29].temperature).toBe(0.2);
    // Hot: disordered; cold: ordered, energy close to the ground state −2
    expect(pts[0].order).toBeLessThan(0.35);
    expect(pts[29].order).toBeGreaterThan(0.97);
    expect(pts[29].energy_per_spin).toBeLessThan(-1.95);
    // The heat capacity peaks near Tc = 2.27 (small lattice: within ±0.6)
    const peak = pts.reduce((a, b) => b.heat_capacity > a.heat_capacity ? b : a);
    expect(Math.abs(peak.temperature - 2.269)).toBeLessThan(0.6);
  });

  test('set_quantum: exact energy, cat state, odd antiferro ring; shown in the app', async ({ page }) => {
    let r = await call(page, 'quantum_magnetism_set_quantum', { spins: 6, coupling: 'ferro', transverse_field: 1, field: 0 });
    expect(r.ok).toBe(true);
    // Free fermions: E0 = −Σ_k √(J² + Γ² − 2JΓ cos k), k = (2n+1)π/N
    let e0 = 0;
    for (let n = 0; n < 6; n++) e0 -= Math.sqrt(2 - 2 * Math.cos(Math.PI * (2 * n + 1) / 6));
    expect(r.result.energy_per_spin).toBeCloseTo(e0 / 6, 4);
    expect(r.result.exact_energy_per_spin).toBeCloseTo(e0 / 6, 4);
    expect(r.result.correlations[0]).toBe(1);
    expect(r.result.correlations).toHaveLength(4);
    expect(r.result.entanglement_bits).toBeGreaterThan(0.5);
    await expect(page.locator('#quantum')).toBeVisible();
    await expect(page.locator('#oN')).toHaveText('6');
    r = await call(page, 'quantum_magnetism_set_quantum', { transverse_field: 0 });
    expect(r.result.top_configurations).toEqual([{ spins: 'dddddd', probability: 0.5 }, { spins: 'uuuuuu', probability: 0.5 }]);
    expect(r.result.entanglement_bits).toBe(1);
    expect(r.result.transverse_magnetization).toBe(0);
    r = await call(page, 'quantum_magnetism_set_quantum', { spins: 5, coupling: 'antiferro' });
    expect(r.result.energy_per_spin).toBe(-0.6);
    expect(r.result.exact_energy_per_spin).toBe(null);
    await expect(page.locator('#qCoupling [data-v="-1"]')).toHaveAttribute('aria-pressed', 'true');
    const bad = await call(page, 'quantum_magnetism_set_quantum', { spins: 14 });
    expect(bad).toEqual({ ok: false, error: 'input.spins must be <= 10' });
  });
});

test.describe('quantum-putt tools', () => {
  test.beforeEach(async ({ page }) => {
    await page.clock.install({ time: 0 });   // the wave only runs through the tools' steps
    await page.clock.pauseAt(1000);   // time stands still: no animation frames on their own
    await open(page, '/quantum-putt/');
  });

  test('list_courses, start_course and get_state', async ({ page }) => {
    let r = await call(page, 'quantum_putt_list_courses', {});
    expect(r.result.courses).toHaveLength(10);
    expect(r.result.courses[8]).toEqual({ id: 'tunnel', number: 9, name: 'Tunnel', par: 4, best: null });
    r = await call(page, 'quantum_putt_start_course', { course: 'slits' });
    expect(r.result).toMatchObject({ course: { id: 'slits', number: 6, name: 'Doppelspalt', par: 3, best: null }, phase: 'aim', strokes: 0,
      ball: { x: 64, y: 230 }, hole: { x: 64, y: 64, radius: 14 }, aim: { angle: 0, strength: 0.6 }, chance_in_hole: null, field: { width: 128, height: 256 } });
    await expect(page.locator('#courseName')).toHaveText('Bahn 6: Doppelspalt');
    await expect(page.locator('#toast')).toHaveText('KI-Agent: Bahn gestartet');
    expect(await call(page, 'quantum_putt_get_state', {})).toEqual(r);
    const tools = await listTools(page);
    expect(tools.find(t => t.name === 'quantum_putt_get_state').annotations.readOnlyHint).toBe(true);
    expect(tools.find(t => t.name === 'quantum_putt_shoot').annotations.readOnlyHint).toBe(false);
  });

  test('shoot and measure: the found point decides about the hole; errors in the wrong phase', async ({ page }) => {
    await call(page, 'quantum_putt_start_course', { course: 'open' });
    expect((await call(page, 'quantum_putt_measure', {})).error).toBe('Nothing to measure – hit the ball with shoot first.');
    let r = await call(page, 'quantum_putt_shoot', { angle: 0, strength: 1 });
    expect(r.result).toMatchObject({ phase: 'fly', strokes: 1, ball: null, aim: { angle: 0, strength: 1 }, wave_time: 0 });
    await expect(page.locator('#btnMain')).toHaveText('Messen');
    expect((await call(page, 'quantum_putt_shoot', { angle: 0, strength: 1 })).error).toBe('The ball is already running as a wave – call measure first.');
    await page.evaluate(() => { Math.random = () => 0.5; });
    // 136 steps = 68 time units: the packet (speed 2 · 1.3 cells per unit) has run from y 226 to about the hole at y 50
    r = await call(page, 'quantum_putt_measure', { steps: 136 });
    expect(r.result.chance_in_hole).toBeGreaterThan(0.4);
    const { x, y } = r.result.found;
    expect(r.result.in_hole).toBe(Math.hypot(x - 64, y - 50) <= 14);
    expect(r.result.in_hole).toBe(true);
    expect(r.result.state).toMatchObject({ phase: 'holed', strokes: 1, course: { best: 1 } });
    await expect(page.locator('#status')).toHaveText('Eingelocht mit 1 Schlag – 1 unter Par! Neuer Bestwert.');
    expect((await call(page, 'quantum_putt_shoot', { angle: 0, strength: 1 })).error).toBe('The ball is already sunk – start the next course with start_course.');
    expect((await call(page, 'quantum_putt_shoot', { angle: 200, strength: 1 })).ok).toBe(false);
    expect((await call(page, 'quantum_putt_start_course', { course: 'golf' })).ok).toBe(false);
  });
});

test.describe('sudoku tools', () => {
  test('get_game, set_cell and new_game: shown on the board, givens and progress protected', async ({ page }) => {
    await open(page, '/sudoku/');
    let r = await call(page, 'sudoku_get_game', {});
    expect(r.result).toMatchObject({ difficulty: 'easy', status: 'playing', empty_squares: 41, rule_conflicts: [], hints_used: 0 });
    expect(r.result.board).toHaveLength(9);
    expect(r.result.board.every(row => /^[1-9.]{9}$/.test(row))).toBe(true);
    expect(r.result.board).toEqual(r.result.givens);
    expect(JSON.stringify(r.result)).not.toMatch(/solution"/);
    const g = await page.evaluate(() => JSON.parse(localStorage.getItem('sudoku.game.v1')));
    // A new game is allowed while nothing is entered
    r = await call(page, 'sudoku_new_game', { difficulty: 'medium' });
    expect(r.result).toMatchObject({ difficulty: 'medium', empty_squares: 49 });
    await expect(page.locator('#lvl')).toHaveText('Mittel');
    const m = await page.evaluate(() => JSON.parse(localStorage.getItem('sudoku.game.v1')));
    expect(m.puzzle).not.toBe(g.puzzle);
    // Enter the right digit in the first empty square
    const i = m.puzzle.indexOf('0'), row = Math.floor(i / 9) + 1, column = (i % 9) + 1, d = Number(m.solution[i]);
    r = await call(page, 'sudoku_set_cell', { row, column, digit: d });
    expect(r.result.board[row - 1][column - 1]).toBe(String(d));
    expect(r.result.empty_squares).toBe(48);
    await expect(page.locator(`#board .cell[data-i="${i}"]`)).toHaveAttribute('data-v', String(d));
    await expect(page.locator('#toast')).toHaveText('KI-Agent: Zahl eingetragen');
    // A digit already in the row breaks a rule
    const j = m.puzzle.indexOf('0', i + 1), jr = Math.floor(j / 9);
    if (jr === row - 1) {
      r = await call(page, 'sudoku_set_cell', { row: jr + 1, column: (j % 9) + 1, digit: d });
      expect(r.result.rule_conflicts).toEqual(expect.arrayContaining([{ row, column }, { row: jr + 1, column: (j % 9) + 1 }]));
      await call(page, 'sudoku_set_cell', { row: jr + 1, column: (j % 9) + 1, digit: 0 });
    }
    // Givens stay, limits like the UI, progress is not discarded
    const k = m.puzzle.search(/[1-9]/);
    expect((await call(page, 'sudoku_set_cell', { row: Math.floor(k / 9) + 1, column: (k % 9) + 1, digit: 1 })).error).toMatch(/given digit/);
    expect((await call(page, 'sudoku_set_cell', { row: 10, column: 1, digit: 1 })).ok).toBe(false);
    expect((await call(page, 'sudoku_set_cell', { row: 1, column: 1, digit: 10 })).ok).toBe(false);
    expect((await call(page, 'sudoku_new_game', { difficulty: 'expert' })).ok).toBe(false);
    expect((await call(page, 'sudoku_new_game', {})).error).toMatch(/only the user can discard/);
    // Clearing again
    r = await call(page, 'sudoku_set_cell', { row, column, digit: 0 });
    expect(r.result.empty_squares).toBe(49);
    const tools = await listTools(page);
    expect(tools.find(t => t.name === 'sudoku_get_game').annotations.readOnlyHint).toBe(true);
    expect(tools.find(t => t.name === 'sudoku_set_cell').annotations.readOnlyHint).toBe(false);
  });

  test('solving through set_cell ends the game; new_game is allowed again', async ({ page }) => {
    await open(page, '/sudoku/');
    const g = await page.evaluate(() => JSON.parse(localStorage.getItem('sudoku.game.v1')));
    let r;
    for (let i = 0; i < 81; i++) {
      if (g.puzzle[i] !== '0') continue;
      r = await call(page, 'sudoku_set_cell', { row: Math.floor(i / 9) + 1, column: (i % 9) + 1, digit: Number(g.solution[i]) });
    }
    expect(r.result).toMatchObject({ status: 'solved', empty_squares: 0 });
    await expect(page.locator('#status')).toHaveText(/^Gelöst in/);
    expect((await call(page, 'sudoku_set_cell', { row: 1, column: 1, digit: 0 })).error).toMatch(/solved/);
    r = await call(page, 'sudoku_new_game', {});
    expect(r.result).toMatchObject({ difficulty: 'easy', status: 'playing' });
  });
});

test.describe('beer-tally tools', () => {
  const pad = n => String(n).padStart(2, '0');
  const d = new Date();
  const TODAY = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  test.beforeEach(async ({ page }) => {
    await open(page, '/beer-tally/');
    await page.evaluate(() => localStorage.setItem('beer-tally.list.v1', JSON.stringify({
      price: 150, people: [{ id: 'a', name: 'Anna' }, { id: 'b', name: 'Ben' }], days: [], payments: [],
    })));
    await page.reload();
  });

  test('add_beers and add_payment change the list shown in the app; get_tally reads it', async ({ page }) => {
    expect(await call(page, 'beer_tally_add_beers', { name: 'anna', count: 3 }))
      .toEqual({ ok: true, result: { name: 'Anna', date: TODAY, beersThatDay: 3, balanceEur: -4.5 } });
    await expect(page.locator(`#tally .cell[data-p="a"][data-d="${TODAY}"]`)).toHaveAttribute('aria-label', /: 3$/);
    await expect(page.locator('#toast')).toHaveText('KI-Agent: Striche gemacht');
    expect(await call(page, 'beer_tally_add_beers', { name: 'Ben', date: '2026-01-02' }))
      .toEqual({ ok: true, result: { name: 'Ben', date: '2026-01-02', beersThatDay: 1, balanceEur: -1.5 } });
    expect(await call(page, 'beer_tally_add_payment', { name: 'Anna', amount: 10 }))
      .toEqual({ ok: true, result: { name: 'Anna', amountEur: 10, balanceEur: 5.5 } });
    await expect(page.locator('#tally tbody tr').first().locator('.bal')).toHaveText('5,50 €');
    expect(await call(page, 'beer_tally_get_tally', {})).toEqual({ ok: true, result: {
      pricePerBeerEur: 1.5,
      people: [
        { name: 'Anna', beers: 3, costEur: 4.5, paidEur: 10, balanceEur: 5.5 },
        { name: 'Ben', beers: 1, costEur: 1.5, paidEur: 0, balanceEur: -1.5 },
      ],
      days: [
        { date: TODAY, pricePerBeerEur: 1.5, beers: { Anna: 3 } },
        { date: '2026-01-02', pricePerBeerEur: 1.5, beers: { Ben: 1 } },
      ],
    } });
  });

  test('only people on the list, limits like the UI', async ({ page }) => {
    expect((await call(page, 'beer_tally_add_beers', { name: 'Carla' })).error).toBe('No person named "Carla" on the list. Known: Anna, Ben');
    expect((await call(page, 'beer_tally_add_beers', { name: 'Anna', count: 51 })).error).toBe('input.count must be <= 50');
    expect((await call(page, 'beer_tally_add_beers', { name: 'Anna', date: '02.01.2026' })).error).toBe('date must be YYYY-MM-DD');
    expect((await call(page, 'beer_tally_add_payment', { name: 'Anna', amount: 0 })).error).toBe('amount must not be 0');
    expect((await call(page, 'beer_tally_add_payment', { name: 'Anna', amount: 10001 })).ok).toBe(false);
    expect((await call(page, 'beer_tally_add_beers', { name: 'Anna', remove: true })).error).toBe('input.remove is not allowed');
    const s = await page.evaluate(() => JSON.parse(localStorage.getItem('beer-tally.list.v1')));
    expect(s.days).toEqual([]);
    expect(s.payments).toEqual([]);
  });
});

test.describe('split-costs tools', () => {
  const pad = n => String(n).padStart(2, '0');
  const d = new Date();
  const TODAY = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  test.beforeEach(async ({ page }) => {
    await open(page, '/split-costs/');
    await page.evaluate(() => localStorage.setItem('split-costs.group.v1', JSON.stringify({
      currency: '€', people: [{ id: 'a', name: 'Anna' }, { id: 'b', name: 'Ben' }, { id: 'c', name: 'Carla' }], entries: [],
    })));
    await page.reload();
  });

  test('add_expense and add_payment change what the app shows; get_summary reads it', async ({ page }) => {
    // 10 € paid by Ben for everyone: 3.34 / 3.33 / 3.33 (the extra cent goes to the first person)
    expect(await call(page, 'split_costs_add_expense', { title: 'Pizza', amount: 10, paidBy: 'ben' })).toEqual({ ok: true, result: {
      expense: { title: 'Pizza', amount: 10, paidBy: 'Ben', date: TODAY, shares: { Anna: 3.34, Ben: 3.33, Carla: 3.33 } },
      balances: [
        { name: 'Anna', paid: 0, share: 3.34, balance: -3.34 },
        { name: 'Ben', paid: 10, share: 3.33, balance: 6.67 },
        { name: 'Carla', paid: 0, share: 3.33, balance: -3.33 },
      ],
    } });
    await expect(page.locator('#entries .name')).toHaveText(['Pizza']);
    await expect(page.locator('#toast')).toHaveText('KI-Agent: Ausgabe eingetragen');
    // 6 € by Carla for Anna and Carla only, on another day
    expect((await call(page, 'split_costs_add_expense', { title: 'Kino', amount: 6, paidBy: 'Carla', splitAmong: ['Anna', 'carla'], date: '2026-01-02' })).ok).toBe(true);
    expect((await call(page, 'split_costs_add_payment', { from: 'Anna', to: 'Ben', amount: 3.34 })).result.balances[0])
      .toEqual({ name: 'Anna', paid: 0, share: 6.34, balance: -3 });
    await expect(page.locator('#balances .bal')).toHaveText(['-3,00 €', '3,33 €', '-0,33 €']);
    expect(await call(page, 'split_costs_get_summary', {})).toEqual({ ok: true, result: {
      currency: '€', totalSpent: 16,
      balances: [
        { name: 'Anna', paid: 0, share: 6.34, balance: -3 },
        { name: 'Ben', paid: 10, share: 3.33, balance: 3.33 },
        { name: 'Carla', paid: 6, share: 6.33, balance: -0.33 },
      ],
      settlement: [{ from: 'Anna', to: 'Ben', amount: 3 }, { from: 'Carla', to: 'Ben', amount: 0.33 }],
      entries: [
        { kind: 'transfer', date: TODAY, amount: 3.34, paidBy: 'Anna', shares: { Ben: 3.34 } },
        { kind: 'expense', title: 'Pizza', date: TODAY, amount: 10, paidBy: 'Ben', shares: { Anna: 3.34, Ben: 3.33, Carla: 3.33 } },
        { kind: 'expense', title: 'Kino', date: '2026-01-02', amount: 6, paidBy: 'Carla', shares: { Anna: 3, Carla: 3 } },
      ],
    } });
  });

  test('only people of the group, limits like the UI', async ({ page }) => {
    expect((await call(page, 'split_costs_add_expense', { title: 'X', amount: 5, paidBy: 'Dora' })).error).toBe('No person named "Dora" in the group. Known: Anna, Ben, Carla');
    expect((await call(page, 'split_costs_add_expense', { title: 'X', amount: 5, paidBy: 'Anna', splitAmong: ['Anna', 'Eve'] })).error).toMatch(/No person named "Eve"/);
    expect((await call(page, 'split_costs_add_expense', { title: 'X', amount: 5, paidBy: 'Anna', splitAmong: [] })).error).toBe('splitAmong must name at least one person');
    expect((await call(page, 'split_costs_add_expense', { title: 'X', amount: 0, paidBy: 'Anna' })).error).toBe('input.amount must be >= 0.01');
    expect((await call(page, 'split_costs_add_expense', { title: 'X', amount: 1000001, paidBy: 'Anna' })).ok).toBe(false);
    expect((await call(page, 'split_costs_add_expense', { title: '  ', amount: 5, paidBy: 'Anna' })).error).toBe('title must not be empty');
    expect((await call(page, 'split_costs_add_expense', { title: 'X', amount: 5, paidBy: 'Anna', date: '2026-02-30' })).error).toBe('date must be a valid YYYY-MM-DD');
    expect((await call(page, 'split_costs_add_payment', { from: 'Anna', to: 'anna', amount: 5 })).error).toBe('from and to must be different people');
    expect((await call(page, 'split_costs_add_payment', { from: 'Anna', to: 'Ben', amount: 5, note: 'x' })).error).toBe('input.note is not allowed');
    expect((await page.evaluate(() => JSON.parse(localStorage.getItem('split-costs.group.v1')))).entries).toEqual([]);
  });
});

test.describe('minesweeper tools', () => {
  // Easy board with known mines: bottom row plus row 8, columns 1–2 (as in minesweeper.spec.mjs)
  const seed = page => page.addInitScript(() => {
    const mine = Array(72).fill(0);
    for (const i of [56, 57, 64, 65, 66, 67, 68, 69, 70, 71]) mine[i] = 1;
    localStorage.setItem('minesweeper.game.v1', JSON.stringify({ level: 'easy', elapsed: 0,
      game: { rows: 9, cols: 8, mines: 10, mine, open: Array(72).fill(0), flag: Array(72).fill(0), status: 'playing', hit: -1 } }));
  });

  test('get_game hides the mines; flag_cell and open_cell play on the board; the mines show once lost', async ({ page }) => {
    await seed(page);
    await open(page, '/minesweeper/');
    let r = await call(page, 'minesweeper_get_game', {});
    expect(r.result).toMatchObject({ level: 'easy', rows: 9, cols: 8, mines: 10, flags: 0, status: 'playing' });
    expect(r.result.board).toEqual(Array(9).fill('########'));
    r = await call(page, 'minesweeper_flag_cell', { row: 8, col: 1 });
    expect(r.result.board[7]).toBe('F#######');
    expect(r.result.mines_left).toBe(9);
    await expect(page.locator('#board .cell[data-i="56"]')).toHaveAttribute('data-v', 'flag');
    expect((await call(page, 'minesweeper_open_cell', { row: 8, col: 1 })).error).toMatch(/has a flag/);
    r = await call(page, 'minesweeper_open_cell', { row: 8, col: 3 });
    expect(r.result.board[7]).toBe('F#4#####');
    await expect(page.locator('#board .cell[data-i="58"]')).toHaveText('4');
    expect((await call(page, 'minesweeper_flag_cell', { row: 8, col: 3 })).error).toMatch(/already open/);
    expect((await call(page, 'minesweeper_open_cell', { row: 10, col: 1 })).error).toMatch(/9 rows and 8 columns/);
    expect((await call(page, 'minesweeper_open_cell', { row: 0, col: 1 })).ok).toBe(false);
    r = await call(page, 'minesweeper_open_cell', { row: 9, col: 8 });
    expect(r.result.status).toBe('lost');
    expect(r.result.board[8]).toBe('*******X');
    expect(r.result.board[7]).toBe('F*4#####');
    expect((await call(page, 'minesweeper_open_cell', { row: 1, col: 1 })).error).toMatch(/game is over/);
  });

  test('new_game deals a fresh board of the chosen size', async ({ page }) => {
    await open(page, '/minesweeper/');
    const r = await call(page, 'minesweeper_new_game', { level: 'medium' });
    expect(r.result).toMatchObject({ level: 'medium', rows: 13, cols: 10, mines: 22, status: 'ready' });
    await expect(page.locator('#board .cell')).toHaveCount(130);
    const o = await call(page, 'minesweeper_open_cell', { row: 7, col: 5 });
    expect(o.result.status).toBe('playing');
    expect(o.result.board[6][4]).toBe('.');
    expect((await call(page, 'minesweeper_new_game', { level: 'huge' })).ok).toBe(false);
  });
});

test.describe('atomic-clock tools', () => {
  test.use({ timezoneId: 'Europe/Berlin', allowedProblems: /Failed to load resource|ERR_FAILED/ });

  test('get_time reads the synchronised time and the device offset', async ({ page }) => {
    await fakeModelContext(page);
    // The server clock is 3 s ahead of this machine (Date header in whole seconds)
    await page.route('**/atomic-clock/manifest.webmanifest?sync=*', route => route.fulfill({
      status: 200, headers: { Date: new Date(Date.now() + 3000).toUTCString() }, body: '' }));
    await page.goto('/atomic-clock/');
    await expect(page.locator('#btnSync')).toBeDisabled(); // sync starts shortly after loading
    await expect(page.locator('#btnSync')).toBeEnabled({ timeout: 15000 });
    const r = (await call(page, 'atomic_clock_get_time', { time_zone: 'UTC' })).result;
    expect(r.synchronised).toBe(true);
    expect(r.accuracy_ms).toBeLessThanOrEqual(100);
    expect(Math.abs(r.device_clock_offset_ms + 3000)).toBeLessThanOrEqual(150);
    expect(Math.abs(Date.parse(r.utc) - (Date.now() + 3000))).toBeLessThan(1500);
    expect(r.utc_offset).toBe('UTC');
    expect(r.big_clock_zone).toBe('Europe/Berlin');
  });

  test('set_time_zone and add_world_clock change the app; unknown zones are refused', async ({ page }) => {
    await fakeModelContext(page);
    await page.route('**/atomic-clock/manifest.webmanifest?sync=*', r => r.abort());
    const t = new Date('2027-07-01T12:00:00Z').getTime();
    await page.clock.install({ time: t - 1000 });
    await page.clock.pauseAt(t);
    await page.goto('/atomic-clock/');
    let r = await call(page, 'atomic_clock_set_time_zone', { time_zone: 'America/New_York' });
    expect(r.result).toEqual({ time_zone: 'America/New_York', local_time: '2027-07-01T08:00:00', utc_offset: 'UTC-4', utc: '2027-07-01T12:00:00.000Z' });
    await expect(page.locator('#zoneName')).toHaveText('New York');
    await expect(page.locator('#toast')).toHaveText('KI-Agent: Zeitzone gewechselt');
    r = (await call(page, 'atomic_clock_get_time', {})).result;
    expect(r.synchronised).toBe(false);
    expect(r.device_clock_offset_ms).toBeNull();
    // US: first Sunday of November 2027 is the 7th, 2:00 EDT = 06:00 UTC
    expect(r.next_offset_change).toEqual({ utc: '2027-11-07T06:00:00.000Z', utc_offset_before: 'UTC-4', utc_offset_after: 'UTC-5' });

    r = await call(page, 'atomic_clock_add_world_clock', { time_zone: 'Australia/Adelaide' });
    expect(r.result.local_time).toBe('2027-07-01T21:30:00');
    expect(r.result.utc_offset).toBe('UTC+9:30');
    await expect(page.locator('#worldList li .name')).toHaveText(['Adelaide']);
    expect((await call(page, 'atomic_clock_add_world_clock', { time_zone: 'Australia/Adelaide' })).result.error).toMatch(/already/);
    expect((await call(page, 'atomic_clock_add_world_clock', { time_zone: 'Mars/Olympus' })).result.error).toMatch(/Unknown time zone/);
    expect((await call(page, 'atomic_clock_set_time_zone', { time_zone: 'Nowhere' })).result.error).toMatch(/Unknown time zone/);
    expect((await call(page, 'atomic_clock_get_time', { time_zone: 'x'.repeat(65) })).ok).toBe(false);
    await expect(page.locator('#zoneName')).toHaveText('New York');
    r = (await call(page, 'atomic_clock_get_time', { time_zone: 'local' })).result;
    expect(r.time_zone).toBe('Europe/Berlin');
    expect(r.world_clocks).toEqual(['Australia/Adelaide']);
  });
});

test.describe('nfc-tags tools', () => {
  test.beforeEach(async ({ page }) => { await fakeNfc(page); await open(page, '/nfc-tags/'); });

  test('get_current_tag and get_tag_history never return Wi-Fi passwords', async ({ page }) => {
    expect((await call(page, 'nfc_tags_get_current_tag', {})).result).toEqual({ tag: null });
    await page.click('#btnScan');
    await expect(page.locator('#btnScan')).toHaveText('Scannen stoppen');
    await page.evaluate(([cred]) => {
      window.__nfc.read('01:02', [{ recordType: 'text', data: 'Hallo' }]);
      window.__nfc.read('03:04', [{ recordType: 'mime', mediaType: 'application/vnd.wfa.wsc', data: cred }]);
    }, [wscCredential({ ssid: 'Heim', key: 'streng-geheim' })]);
    const cur = (await call(page, 'nfc_tags_get_current_tag', {})).result.tag;
    expect(cur.serial_number).toBe('03:04');
    expect(cur.records).toEqual([{ kind: 'wifi', ssid: 'Heim', auth: 'wpa2', has_password: true }]);
    const all = (await call(page, 'nfc_tags_get_tag_history', {})).result;
    expect(all.total).toBe(2);
    expect(JSON.stringify(all)).not.toContain('streng-geheim');
    const found = (await call(page, 'nfc_tags_get_tag_history', { search: 'hallo' })).result;
    expect(found.tags.map(x => x.serial_number)).toEqual(['01:02']);
  });

  test('prepare_tag_content fills the write form but writes nothing', async ({ page }) => {
    const r = await call(page, 'nfc_tags_prepare_tag_content', { kind: 'url', url: 'example.com' });
    expect(r.ok).toBe(true);
    // same size as in nfc-tags.spec.mjs: 17-byte URL record + 3 bytes TLV
    expect(r.result).toMatchObject({ prepared: true, kind: 'url', estimated_bytes: 20, fits_on: 'NTAG213' });
    await expect(page.locator('#writeView')).toBeVisible();
    await expect(page.locator('#urlIn')).toHaveValue('example.com');
    expect(await page.evaluate(() => window.__nfc.pending + window.__nfc.written.length)).toBe(0);
    const bad = await call(page, 'nfc_tags_prepare_tag_content', { kind: 'wifi', ssid: 'X', password: 'kurz' });
    expect(bad.ok).toBe(false);
    expect((await call(page, 'nfc_tags_prepare_tag_content', { kind: 'fax' })).ok).toBe(false);
  });
});
